    input [3:0] data_in,
    input load,
    input clk,
    output reg [3:0] data_out,
    output reg valid
);

reg [3:0] reg_data;

always @(posedge clk) begin
    if (load) begin
        reg_data <= data_in;
    end else begin
        case(ctrl)
            2'b00: begin
                data_out <= reg_data;
                valid <= 1'b1;
