module NIOS_SYSTEMV3_JTAG_UART_sim_scfifo_r (
    input clk,
    input fifo_rd,
    input rst_n,
    output fifo_EF,
    output [7:0] fifo_rdata,
    output rfifo_full,
    output [5:0] rfifo_used
);

    reg [31:0] bytes_left;
    wire fifo_EF;
    reg fifo_rd_d;
    wire [7:0] fifo_rdata;
    wire new_rom;
    wire [31:0] num_bytes;
    wire [6:0] rfifo_entries;
    wire rfifo_full;
    wire [5:0] rfifo_used;

    // Generate rfifo_entries
    always @(posedge clk or negedge rst_n) begin
        if (~rst_n) begin
            bytes_left <= 32'h0;
            fifo_rd_d <= 1'b0;
        end else begin
            fifo_rd_d <= fifo_rd;
            // decrement on read
            if (fifo_rd_d) begin
                bytes_left <= bytes_left - 1'b1;
            end
            // catch new contents
            if (new_rom) begin
                bytes_left <= num_bytes;
            end
        end
