    assign rfifo_full = (bytes_left > 7'h40);
    assign rfifo_entries = (rfifo_full) ? 7'h40 : bytes_left;
    assign rfifo_used = rfifo_entries[5:0];

    // Set unused outputs to default values
    assign new_rom = 1'b0;
    assign num_bytes = 32'b0;
    assign fifo_rdata = 8'b0;

