	input reg_write_m,
	input [2:0] reg_write_adr_m,
	input reg_write_w,
	input [2:0] reg_write_adr_w,

	input PC_source,

	output reg stall_f,
	output reg stall_d,
	output reg flush_d,
	output reg  flush_e,

	output reg  [1:0] forward1_e,
	output reg  [1:0] forward2_e
	);

