    input clk,
    input [12:0] slow_rate,
    output speaker_out
);

reg [12:0] counter;
reg speaker;
reg [12:0] slow_rate_old;

initial begin
    counter = 0;
    slow_rate_old = 0;
    speaker = 1'b0;
end

