        if(counter == slow_rate) begin
            speaker <= ~speaker;
            counter <= 0;
        end
        else begin
            counter <= counter + 1;
        end
    end
    else begin
        speaker <= 1'b0;
        counter <= 0;
    end
end

assign speaker_out = speaker;

endmodule
